package com.campusmart.repository;
import com.campusmart.entity.*;import java.math.*;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface ProductRepository extends JpaRepository<Product,Long>{@Query("select p from Product p where p.available=true and (:q is null or lower(p.name) like lower(concat('%',:q,'%')) or lower(p.description) like lower(concat('%',:q,'%'))) and (:category is null or lower(p.category.name)=lower(:category)) and (:condition is null or p.condition=:condition) and (:maxPrice is null or p.price<=:maxPrice) order by p.createdAt desc")List<Product>search(@Param("q")String q,@Param("category")String category,@Param("condition")Product.Condition condition,@Param("maxPrice")BigDecimal maxPrice);long countByAvailableTrue();}
